/**
 * Self-hosted hospital photos (best for SEO: indexed in Google Images under this domain,
 * included in schema + image sitemap, no API cost).
 *
 * Generated by `npm run photos` from originals in /photos — do not edit photos.json by hand.
 * Until photos are added, the gallery shows live photos from the Google Business Profile instead.
 */
import data from './photos.json';

export const localPhotos = Array.isArray(data) ? data : [];

export const photoSrc = (p, w) => `/images/hospital/${p.slug}-${w}.webp`;
export const photoSrcSet = (p) => p.widths.map((w) => `${photoSrc(p, w)} ${w}w`).join(', ');
export const photoLargest = (p) => photoSrc(p, p.widths[p.widths.length - 1]);
export const photoMedium = (p) => photoSrc(p, p.widths.find((w) => w >= 960) || p.widths[p.widths.length - 1]);

/** The hospital's own photo in the normalised image shape used by <StockImage> (badge: "Gurudev Hospital"). */
export const hospitalImage = (slug) => {
  const p = localPhotos.find((x) => x.slug === slug);
  if (!p) return null;
  const w = Math.min(p.width, p.widths.at(-1));
  return { url: (width) => photoSrc(p, width), widths: p.widths, alt: p.alt, caption: p.caption, width: w, height: Math.round((w / p.width) * p.height), representative: false };
};
